"""Explain waitqueue signal exits and careful cleanup."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1461': ('대기 중 집에 가라는 연락을 받으면 명단에서 이름을 빼야 합니다. 그래야 다음 호출이 이미 떠날 사람 대신 다른 사람에게 갑니다. 다만 내 차례가 이미 준비됐는지도 마지막으로 확인합니다.', '신호를 받은 준비 함수의 제거와 호출자의 조건 재검사를 연결합니다.', 'prepare에서 허용 신호 확인 → 항목 제거 → -ERESTARTSYS → 호출자가 조건 재검사 → 참이면 성공, 거짓이면 오류 처리를 그리세요.', ['prepare_to_wait_event는 기다릴 준비를 하면서 신호도 확인합니다. 신호는 태스크에 전달하는 알림입니다. 모든 신호가 모든 기다림을 멈추지는 않고 signal_pending_state가 지정한 대기 상태에서 중단 가능한지 판단합니다.', '대기열 잠금을 잡은 상태에서 허용되는 신호가 보이면 list_del_init로 자신의 항목을 뺍니다. init는 항목의 앞뒤 링크를 다시 자기 자신으로 돌리는 부분입니다. 카드의 연결을 지우는 것이지 태스크 메모리를 free하는 것은 아닙니다.', '이 경로의 반환값은 -ERESTARTSYS입니다. 커널에서 재시작 가능한 시스템 호출 처리와 연결되는 내부 오류 코드이며, 이름만으로 사용자 프로그램에 무조건 그대로 전달되거나 무조건 재시작된다고 단정하지 않습니다. 앞의 rcuwait가 사용한 -EINTR과 다른 값입니다.', '왜 먼저 항목을 뺄까요? 이후 조건 변경과 깨우기가 발생할 때 이미 중단하려는 항목을 다시 고르지 않게 하려는 것입니다. 특히 한도에 따라 선택되는 exclusive 항목이라면 다음 대기자에게 기회를 줄 수 있어야 합니다.', '하지만 이 반환값만 보고 기다리던 조건이 거짓이라고 결정하지 않습니다. 공통 대기 매크로는 prepare 이후 조건부터 재검사합니다. 이미 선택된 대기자의 조건이 맞았다면 신호 오류보다 조건 성공으로 끝낼 기회를 줍니다.', '허용되는 신호가 없으면 아직 연결되지 않은 항목을 등록합니다. EXCLUSIVE이면 목록 끝에, 아니면 일반 삽입 helper로 넣고 대기 상태를 설정합니다. 신호 경로에서는 이 상태 설정을 하지 않습니다. 직접 호출하는 코드는 제거와 상태의 정리 책임까지 함께 살펴야 합니다.'], [('prepare_to_wait_event의 허용 신호 경로 반환값은?', ['언제나 rcuwait와 똑같은 -EINTR이에요', '-ERESTARTSYS예요'], '원문 대입은 ret=-ERESTARTSYS입니다. 서로 다른 대기 API는 오류 약속도 다를 수 있으므로 앞에서 본 -EINTR로 바꾸어 외우면 안 됩니다.'), ('허용 신호를 보고 오류를 돌려주는 경로에서 항목은 명단에 남을까요?', ['아니요. list_del_init로 빼요', '네. 다음 깨우기가 언젠가 빼 줄 때까지 남아요'], '함수가 잠금 아래 직접 항목을 제거합니다. 뒤의 깨우기가 중단할 대기자를 다시 선택하지 않게 하므로 다음 wake에 제거를 맡기는 방식이 아닙니다.')]), 'os1462': ('출구가 두 개 있는 길을 생각해 봅시다. 보통 출구는 정리대를 지나지만, 다른 출구는 앞에서 이미 명단 정리를 한 뒤 바로 나갑니다. 두 길이 어디서 정리하는지 따로 따라가야 합니다.', '일반 waitqueue 매크로의 조건 우선 판정과 신호 오류 출구를 읽습니다.', 'prepare → 조건 참이면 break → finish_wait. 조건 거짓+중단 오류이면 __ret 저장 → goto __out을 그리세요. __out이 finish_wait 아래에 있다는 점에 표시하세요.', ['___wait_event는 대기 반복 코드를 펼쳐 넣는 매크로입니다. 스택에 임시 대기 항목을 만들고 init_wait_entry로 초기화합니다. 스택은 현재 함수 실행 동안 쓰는 공간이므로 반환 전에 연결 정리가 맞아야 합니다.', 'long __ret = ret는 결과를 담는 지역 변수입니다. 원문의 explicit shadow 주석은 바깥에 같은 이름의 변수가 있어도 이 안에서 별도 변수를 쓰도록 의도했다는 뜻입니다. GNU C의 ({ ... }) 표기는 여러 문장을 묶어 마지막 값으로 결과를 만드는 확장 문법입니다.', '매 반복은 prepare_to_wait_event의 반환값을 __int에 받습니다. 그다음 condition을 먼저 검사합니다. 참이면 break로 반복을 끝내고 finish_wait를 실행합니다. 준비 함수가 신호 오류를 알렸더라도 조건이 맞으면 이 성공 길을 먼저 고릅니다.', '조건이 거짓일 때 중단 가능한 대기 상태와 __int 오류를 확인합니다. 오류가 있으면 __ret에 담고 goto __out으로 이동합니다. goto는 이름 붙인 코드 위치로 이동하는 명령이고 __label__은 여기서 쓸 지역 이름표를 선언합니다.', '__out은 finish_wait 호출보다 아래에 있습니다. 따라서 이 신호 오류 길은 finish_wait를 건너뜁니다. prepare_to_wait_event가 신호 경로에서 이미 list_del_init로 제거하고 새 대기 상태를 설정하지 않는 계약과 함께 읽어야 합니다. 앞서 본 rcuwait의 모든 종료가 공통 finish를 거치는 흐름과 다릅니다.', '조건도 거짓이고 오류도 없다면 cmd에 해당하는 대기 명령을 실행하고 반복합니다. 깨어난 뒤 조건을 다시 확인하므로 한 번만 평가된다고 가정하면 안 됩니다. 직접 다른 대기 코드를 작성할 때 이 goto만 복사해 정리를 생략해도 된다는 뜻은 아닙니다.'], [('이 일반 waitqueue 매크로의 신호 오류 길도 항상 finish_wait를 부를까요?', ['네. 어느 길도 예외 없이 finish를 거쳐요', '아니요. goto __out으로 finish 아래에 갑니다'], '오류 goto가 도착하는 이름표는 finish_wait 뒤입니다. 준비 함수가 이미 항목을 제거하는 계약이 있으므로 rcuwait의 흐름과 같다고 외우면 틀립니다.'), ('prepare가 돌아온 뒤 조건 성공과 신호 오류 중 먼저 확인하는 것은?', ['조건 성공이에요', '무조건 신호 오류예요'], 'if(condition)이 오류 분기보다 앞에 있습니다. 조건이 참이면 break하고 finish로 가므로, 오류가 보고됐다는 이유만으로 조건 확인을 건너뛰지 않습니다.')]), 'os1463': ('접수 명단의 앞뒤 연결을 정리할 때 한쪽만 바뀐 순간을 보고 모두 끝났다고 생각하면 위험합니다. 두 연결을 확인하고, 아직 남아 있으면 잠금 아래 정리합니다.', 'finish_wait의 상태 복구와 careful 목록 검사의 조건을 배웁니다.', 'TASK_RUNNING 복구 → next·prev careful 확인 → 연결이 남으면 잠금 → list_del_init → 잠금 해제를 그리세요.', ['finish_wait는 기다림을 마칠 때 쓰는 정리 함수입니다. 첫 동작은 __set_current_state(TASK_RUNNING)입니다. 현재 태스크의 대기 상태를 실행 가능한 상태로 돌리는 것이며 태스크 메모리를 없애는 일이 아닙니다.', '다음에는 list_empty_careful로 자신의 대기 항목 링크를 확인합니다. careful은 next와 prev 두 방향이 모두 자기 자신을 가리키는 빈 상태인지 살핍니다. 단순히 다음 주소 하나만 보고 제거가 끝났다고 판단하는 검사와 다릅니다.', '왜 두 방향을 볼까요? 다른 CPU가 항목을 빼면서 링크를 정리할 수 있습니다. 한쪽만 바뀐 상태를 최종 빈 상태로 착각하면 그 CPU가 아직 다루는 임시 대기 항목을 너무 일찍 끝낼 수 있습니다. 원문은 이 조회와 다른 변경자의 잠금 규약을 함께 요구합니다.', '아직 연결된 것으로 보이면 spin_lock_irqsave로 대기열 잠금을 잡고 list_del_init로 제거합니다. 이후 잠금을 풀고 인터럽트 상태를 복원합니다. 이미 안전하게 빈 상태라면 이 제거 구간은 건너뜁니다.', '잠금 없이 careful 조회를 한다고 모든 종류의 동시 목록 변경이 허용되는 것은 아닙니다. 관련된 제거와 관측의 정해진 규약 안에서 사용합니다. 다른 CPU가 이 항목을 마음대로 다시 삽입하는 상황까지 이 함수 하나가 해결해 주지는 않습니다.', '직접 대기 반복문을 썼다면 끝난 뒤 등록된 항목이 남지 않도록 finish 흐름을 맞추세요. 특히 스택의 항목은 함수가 돌아간 뒤에도 깨우는 쪽이 계속 접근하면 안 됩니다. 목록 정리와 메모리 수명을 함께 지켜야 안전합니다.'], [('finish_wait가 맨 먼저 하는 일은?', ['현재 태스크의 메모리를 free해요', 'TASK_RUNNING 상태로 복구해요'], '첫 실행문은 __set_current_state(TASK_RUNNING)입니다. 기다림의 상태를 정리할 뿐 현재 태스크를 삭제하는 함수가 아닙니다.'), ('잠금 밖에서 빈 상태를 확인할 때 쓰는 함수는?', ['list_empty_careful이에요', 'next 하나만 임의로 읽는 검사예요'], '원문은 next와 prev를 확인하는 careful 검사를 사용합니다. 다른 변경자의 잠금 규약까지 전제하므로 단순한 주소 하나 검사로 바꾸어도 된다고 생각하면 안 됩니다.')]), 'os1464': ('사람을 실제로 불러 깨웠을 때만 접수 카드를 빼는 담당자가 있습니다. 연락을 시도했다는 사실만으로 카드를 무조건 빼면 아직 기다리는 사람을 잃을 수 있습니다.', 'autoremove 콜백의 깨우기 결과와 조건부 연결 제거를 이해합니다.', 'default 결과 0 → 카드 유지·0 반환, 결과 1 → careful 제거·1 반환을 두 줄로 적으세요. 제거해도 카드 메모리를 free하는 것은 아닙니다.', ['autoremove_wake_function은 먼저 default_wake_function을 호출합니다. default는 기본이라는 뜻이고, 이 함수는 기본 깨우기를 시도한 뒤 그 결과에 따라 자기 대기 항목을 자동 제거합니다.', '결과를 ret에 담고 if(ret)를 검사합니다. C에서 0은 거짓이고 0이 아닌 값은 참입니다. 이 기본 깨우기의 정상 결과에서 성공은 1, 깨우지 못한 경우는 0이므로 성공한 경우에 제거 경로로 갑니다.', '0이면 목록 제거를 하지 않고 그대로 0을 반환합니다. 콜백이 실행됐어도 항목은 남을 수 있습니다. 함수 호출, 깨우기 성공, 대기열 제거를 세 가지 사건으로 나누어 읽어야 합니다.', '성공하면 list_del_init_careful을 씁니다. 항목을 앞뒤 이웃의 연결에서 빼고 자기 링크를 빈 상태로 돌리되, 반대편의 list_empty_careful 관측과 맞도록 접근 순서를 갖춘 helper입니다. v6.12 구현은 prev를 자기 자신으로 놓고 next를 release 방식으로 공개합니다.', '이 공개를 finish_wait 쪽의 careful 검사가 받아 정리 완료를 판단하는 데 사용합니다. release와 acquire는 앞뒤 메모리 접근 순서를 맞추는 짝입니다. 임의의 재삽입이나 잠금 없는 모든 변경까지 자동으로 안전하게 만드는 것은 아닙니다.', '제거 뒤에도 ret는 그대로 호출자에게 돌아갑니다. 항목이나 태스크의 메모리를 직접 free하지 않습니다. 또한 깨운 태스크는 기다리던 실제 조건을 다시 확인해야 합니다. 한 번 목록에서 제거됐다는 사실이 자원을 이미 얻었다는 증거는 아닙니다.'], [('기본 깨우기 결과가 0이면 autoremove가 항목을 뺄까요?', ['네. 호출됐으니 무조건 빼요', '아니요. 등록을 유지해요'], '삭제 코드는 if(ret) 안에 있습니다. 0이면 그 안에 들어가지 않으므로 콜백을 호출한 사실만으로 제거됐다고 판단하면 안 됩니다.'), ('깨우기에 성공했을 때 어떤 helper로 연결을 정리할까요?', ['list_del_init_careful이에요', '메모리 free만 호출해요'], '원문은 careful 방식의 목록 제거와 빈 링크 복구를 수행합니다. 항목 메모리 자체를 반납하는 free는 호출하지 않습니다.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_361.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
